-- =====================================================
-- PROJECT 2: SALES PERFORMANCE ANALYSIS
-- TASK 1: TOTAL REVENUE
-- Business Question:
-- What is the total revenue generated by NovaMart?
-- =====================================================

SELECT
    SUM(
        quantity
        * unit_price
        * (1 - discount_percent / 100)
    ) AS total_revenue       -- Calculate revenue after discounts
FROM order_items;            -- Revenue is calculated from individual items


-- =====================================================
-- PROJECT 2: SALES PERFORMANCE ANALYSIS
-- TASK 2: REVENUE BY YEAR
-- Business Question:
-- How much revenue did NovaMart generate in each year?
-- =====================================================

SELECT
    YEAR(o.order_date) AS order_year,       -- Extract the year of the order

    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS total_revenue                      -- Calculate revenue after discounts

FROM orders AS o                            -- Get the order date
JOIN order_items AS oi                      -- Connect orders to their products
    ON o.order_id = oi.order_id             -- Match each item to its order

GROUP BY YEAR(o.order_date)                  -- Create one group for each year
ORDER BY order_year;                         -- Display years chronologically



-- =====================================================
-- PROJECT 2: SALES PERFORMANCE ANALYSIS
-- TASK 3: REVENUE BY MONTH
-- Business Question:
-- How does revenue vary across the months?
-- =====================================================

SELECT
    MONTH(o.order_date) AS order_month,     -- Extract the month number

    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS total_revenue                      -- Calculate revenue after discounts

FROM orders AS o                            -- Get order dates
JOIN order_items AS oi                      -- Connect orders to their items
    ON o.order_id = oi.order_id             -- Match each item to its order

GROUP BY MONTH(o.order_date)                -- Group all orders by month
ORDER BY order_month;                       -- Display January → December


-- =====================================================
-- PROJECT 2: SALES PERFORMANCE ANALYSIS
-- TASK 4: SALES DATE COVERAGE
-- Business Question:
-- What is the earliest and latest order date?
-- =====================================================

SELECT
    MIN(order_date) AS earliest_order_date,  -- First order date in the dataset
    MAX(order_date) AS latest_order_date     -- Last order date in the dataset
FROM orders;                                 -- Check the orders table


-- =====================================================
-- PROJECT 2: SALES PERFORMANCE ANALYSIS
-- TASK 5: REVENUE BY SALES CHANNEL
-- Business Question:
-- How much revenue does each sales channel generate?
-- =====================================================

SELECT
    o.channel,                              -- Sales channel

    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS total_revenue                      -- Revenue after discounts

FROM orders AS o                            -- Get the sales channel
JOIN order_items AS oi                      -- Connect orders to their items
    ON o.order_id = oi.order_id             -- Match each item to its order

GROUP BY o.channel                          -- Group revenue by channel
ORDER BY total_revenue DESC;                -- Highest revenue channel first


-- =====================================================
-- PROJECT 2: SALES PERFORMANCE ANALYSIS
-- TASK 6: AVERAGE ORDER VALUE (AOV)
-- Business Question:
-- What is the average revenue generated per order?
-- =====================================================

SELECT
    AVG(order_revenue) AS average_order_value   -- Calculate average revenue per order
FROM (
    
    SELECT
        o.order_id,                              -- Identify each order

        SUM(
            oi.quantity
            * oi.unit_price
            * (1 - oi.discount_percent / 100)
        ) AS order_revenue                       -- Calculate revenue for each order

    FROM orders AS o                             -- Get the orders
    JOIN order_items AS oi                       -- Connect orders to their items
        ON o.order_id = oi.order_id              -- Match each item to its order

    GROUP BY o.order_id                          -- Calculate one revenue value per order

) AS order_totals;                               -- Treat order-level results as a temporary table


-- =====================================================
-- PROJECT 2: SALES PERFORMANCE ANALYSIS
-- TASK 7: ORDERS BY SALES CHANNEL
-- Business Question:
-- How many orders came through each sales channel?
-- =====================================================

SELECT
    channel,                         -- Sales channel
    COUNT(*) AS orders_count         -- Count orders from each channel
FROM orders                          -- Use the orders table
GROUP BY channel                     -- Group orders by channel
ORDER BY orders_count DESC;          -- Show channels with most orders first


-- =====================================================
-- PROJECT 2: SALES PERFORMANCE ANALYSIS
-- TASK 8: AVERAGE ORDER VALUE BY SALES CHANNEL
-- Business Question:
-- What is the average order value for each sales channel?
-- =====================================================

SELECT
    channel,                                -- Sales channel
    AVG(order_revenue) AS average_order_value -- Average revenue per order

FROM (
    
    SELECT
        o.order_id,                          -- Identify each order
        o.channel,                          -- Keep the sales channel

        SUM(
            oi.quantity
            * oi.unit_price
            * (1 - oi.discount_percent / 100)
        ) AS order_revenue                  -- Calculate revenue for each order

    FROM orders AS o                        -- Get orders and channels
    JOIN order_items AS oi                  -- Connect orders to their items
        ON o.order_id = oi.order_id         -- Match each item to its order

    GROUP BY
        o.order_id,
        o.channel                           -- Calculate one revenue value per order

) AS order_totals                           -- Temporary order-level result

GROUP BY channel                             -- Group the calculated orders by channel
ORDER BY average_order_value DESC;           -- Highest AOV first


-- =====================================================
-- PROJECT 2: SALES PERFORMANCE ANALYSIS
-- TASK 9: REVENUE BY PRODUCT CATEGORY
-- Business Question:
-- Which product categories generate the most revenue?
-- =====================================================

SELECT
    c.category_name,                         -- Product category

    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS total_revenue                       -- Revenue after discounts

FROM order_items AS oi                       -- Start with sales line items
JOIN products AS p                           -- Connect items to products
    ON oi.product_id = p.product_id          -- Match product IDs
JOIN categories AS c                         -- Connect products to categories
    ON p.category_id = c.category_id         -- Match category IDs

GROUP BY c.category_name                     -- Group revenue by category
ORDER BY total_revenue DESC;                 -- Highest-revenue category first


-- =====================================================
-- PROJECT 2: SALES PERFORMANCE ANALYSIS
-- TASK 10: TOP PRODUCTS BY REVENUE
-- Business Question:
-- Which individual products generate the most revenue?
-- =====================================================

SELECT
    p.product_id,                            -- Identify the product
    p.product_name,                          -- Product name

    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS total_revenue                       -- Revenue generated by the product

FROM order_items AS oi                       -- Start with sales line items
JOIN products AS p                           -- Connect items to products
    ON oi.product_id = p.product_id          -- Match product IDs

GROUP BY
    p.product_id,
    p.product_name                           -- Calculate revenue per product

ORDER BY total_revenue DESC                  -- Highest-revenue products first
LIMIT 10;                                    -- Show the top 10 products

-- =====================================================
-- PROJECT 2: SALES PERFORMANCE ANALYSIS
-- TASK 11: REVENUE BY STORE
-- Business Question:
-- Which stores generate the most revenue?
-- =====================================================

SELECT
    s.store_id,                              -- Identify the store
    s.store_code,                            -- Store code
    s.city,                                  -- Store city
    s.region,                                -- Store region

    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS total_revenue                       -- Revenue generated by the store

FROM orders AS o                             -- Start with orders
JOIN order_items AS oi                       -- Connect orders to their items
    ON o.order_id = oi.order_id              -- Match each item to its order

JOIN stores AS s                             -- Connect orders to stores
    ON o.store_id = s.store_id               -- Match each order to its store

GROUP BY
    s.store_id,
    s.store_code,
    s.city,
    s.region                                 -- Calculate revenue for each store

ORDER BY total_revenue DESC;                 -- Highest-revenue stores first



-- =====================================================
-- PROJECT 2: SALES PERFORMANCE ANALYSIS
-- TASK 12: REVENUE BY REGION
-- Business Question:
-- How much revenue does each region generate?
-- =====================================================

SELECT
    s.region,                                -- Identify the region

    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS total_revenue                       -- Calculate revenue after discounts

FROM orders AS o                             -- Start with orders
JOIN order_items AS oi                       -- Connect orders to their items
    ON o.order_id = oi.order_id              -- Match order IDs

JOIN stores AS s                             -- Connect orders to stores
    ON o.store_id = s.store_id               -- Match store IDs

GROUP BY
    s.region                                 -- Calculate revenue for each region

ORDER BY total_revenue DESC;                 -- Highest-revenue region first


-- =====================================================
-- PROJECT 2: SALES PERFORMANCE ANALYSIS
-- TASK 13: REVENUE BY CUSTOMER
-- Business Question:
-- Which customers generate the most revenue?
-- =====================================================

SELECT
    c.customer_id,                           -- Identify the customer
    c.first_name,                            -- Customer first name
    c.last_name,                             -- Customer last name

    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS total_revenue                       -- Revenue generated by the customer

FROM customers AS c                          -- Start with customers
JOIN orders AS o                              -- Connect customers to their orders
    ON c.customer_id = o.customer_id         -- Match customer IDs

JOIN order_items AS oi                        -- Connect orders to their items
    ON o.order_id = oi.order_id               -- Match order IDs

GROUP BY
    c.customer_id,
    c.first_name,
    c.last_name                               -- Calculate revenue per customer

ORDER BY total_revenue DESC                   -- Highest-revenue customers first
LIMIT 10;                                     -- Show the top 10 customers


-- =====================================================
-- PROJECT 2: SALES PERFORMANCE ANALYSIS
-- TASK 14: REVENUE BY YEAR AND SALES CHANNEL
-- Business Question:
-- How much revenue did each sales channel generate
-- in each year?
-- =====================================================

SELECT
    YEAR(o.order_date) AS order_year,        -- Extract the year
    o.channel,                               -- Identify the sales channel

    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS total_revenue                       -- Calculate revenue after discounts

FROM orders AS o                             -- Start with orders
JOIN order_items AS oi                       -- Connect orders to their items
    ON o.order_id = oi.order_id              -- Match order IDs

GROUP BY
    YEAR(o.order_date),
    o.channel                                -- Group by both year and channel

ORDER BY
    order_year,
    total_revenue DESC;                      -- Sort by year, then highest revenue
    
    
    
    -- =====================================================
-- PROJECT 2: SALES PERFORMANCE ANALYSIS
-- TASK 15: REVENUE BY ORDER STATUS
-- Business Question:
-- How much revenue is associated with each order status?
-- =====================================================

SELECT
    o.status,                                -- Identify the order status

    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS total_revenue                       -- Calculate revenue associated with the status

FROM orders AS o                             -- Start with orders
JOIN order_items AS oi                       -- Connect orders to their items
    ON o.order_id = oi.order_id              -- Match order IDs

GROUP BY
    o.status                                 -- Group revenue by order status

ORDER BY total_revenue DESC;                 -- Highest associated revenue first


-- =====================================================
-- PROJECT 2: SALES PERFORMANCE ANALYSIS
-- TASK 16: UNITS SOLD BY PRODUCT CATEGORY
-- Business Question:
-- Which product categories sell the highest number
-- of units?
-- =====================================================

SELECT
    c.category_name,                         -- Identify the product category

    SUM(
        oi.quantity
    ) AS units_sold                           -- Total number of units sold

FROM order_items AS oi                       -- Start with order line items
JOIN products AS p                           -- Connect items to products
    ON oi.product_id = p.product_id          -- Match product IDs

JOIN categories AS c                         -- Connect products to categories
    ON p.category_id = c.category_id         -- Match category IDs

GROUP BY
    c.category_name                          -- Calculate units sold per category

ORDER BY
    units_sold DESC;                         -- Highest unit sales first
    
    
    -- =====================================================
-- PROJECT 2: SALES PERFORMANCE ANALYSIS
-- TASK 17: AVERAGE SELLING PRICE BY CATEGORY
-- Business Question:
-- What is the average selling price of items
-- in each product category?
-- =====================================================

SELECT 
    c.category_name, AVG(oi.unit_price) AS average_selling_price
FROM
    order_items AS oi
        JOIN
    products AS p ON oi.product_id = p.product_id
        JOIN
    categories AS c ON p.category_id = c.category_id
GROUP BY c.category_name
ORDER BY average_selling_price DESC;              -- Highest average price first


-- =====================================================
-- PROJECT 2: SALES PERFORMANCE ANALYSIS
-- TASK 18: REVENUE PER UNIT BY CATEGORY
-- Business Question:
-- How much revenue does NovaMart generate on average
-- for each unit sold in each category?
-- =====================================================

SELECT
    c.category_name,                         -- Identify the product category

    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS total_revenue,                      -- Total revenue after discounts

    SUM(
        oi.quantity
    ) AS units_sold,                         -- Total units sold

    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    )
    /
    SUM(oi.quantity) AS revenue_per_unit     -- Revenue generated per unit

FROM order_items AS oi                       -- Start with order line items
JOIN products AS p                           -- Connect items to products
    ON oi.product_id = p.product_id          -- Match product IDs

JOIN categories AS c                         -- Connect products to categories
    ON p.category_id = c.category_id         -- Match category IDs

GROUP BY
    c.category_name                          -- Calculate metrics per category

ORDER BY
    revenue_per_unit DESC;                   -- Highest revenue per unit first
    
    
    -- =====================================================
-- PROJECT 2: SALES PERFORMANCE ANALYSIS
-- TASK 19: DISCOUNT AMOUNT BY CATEGORY
-- Business Question:
-- How much discount value was given in each
-- product category?
-- =====================================================

SELECT
    c.category_name,                         -- Identify the product category

    SUM(
        oi.quantity
        * oi.unit_price
        * (oi.discount_percent / 100)
    ) AS total_discount_amount               -- Total discount value given

FROM order_items AS oi                       -- Start with order line items
JOIN products AS p                           -- Connect items to products
    ON oi.product_id = p.product_id          -- Match product IDs

JOIN categories AS c                         -- Connect products to categories
    ON p.category_id = c.category_id         -- Match category IDs

GROUP BY
    c.category_name                          -- Calculate discount per category

ORDER BY
    total_discount_amount DESC;              -- Highest discount amount first
    
    
    -- =====================================================
-- PROJECT 2: SALES PERFORMANCE ANALYSIS
-- TASK 20: AVERAGE DISCOUNT RATE BY CATEGORY
-- Business Question:
-- Which product categories have the highest
-- average discount rate?
-- =====================================================

SELECT
    c.category_name,                         -- Identify the product category

    AVG(
        oi.discount_percent
    ) AS average_discount_rate               -- Calculate average discount percentage

FROM order_items AS oi                       -- Start with order line items
JOIN products AS p                           -- Connect items to products
    ON oi.product_id = p.product_id          -- Match product IDs

JOIN categories AS c                         -- Connect products to categories
    ON p.category_id = c.category_id         -- Match category IDs

GROUP BY
    c.category_name                          -- Calculate discount rate per category

ORDER BY
    average_discount_rate DESC;              -- Highest average discount first
    
    
    -- =====================================================
-- PROJECT 2: SALES PERFORMANCE ANALYSIS
-- TASK 21: TOTAL PROFIT
-- Business Question:
-- How much gross profit did NovaMart generate?
-- =====================================================

SELECT
    SUM(
        (
            oi.unit_price
            * (1 - oi.discount_percent / 100)
            - p.cost_price
        )
        * oi.quantity
    ) AS total_profit                         -- Total profit after discounts and product costs

FROM order_items AS oi                       -- Start with sales line items
JOIN products AS p                           -- Connect items to product costs
    ON oi.product_id = p.product_id;          -- Match each product
    
    
    -- =====================================================
-- PROJECT 2: SALES PERFORMANCE ANALYSIS
-- TASK 22: GROSS PROFIT BY CATEGORY
-- Business Question:
-- Which product categories generate the most
-- gross profit?
-- =====================================================

SELECT
    c.category_name,                         -- Identify the product category

    SUM(
        (
            oi.unit_price
            * (1 - oi.discount_percent / 100)
            - p.cost_price
        )
        * oi.quantity
    ) AS gross_profit                        -- Calculate total gross profit

FROM order_items AS oi                       -- Start with sales line items
JOIN products AS p                           -- Connect items to product costs
    ON oi.product_id = p.product_id          -- Match product IDs

JOIN categories AS c                         -- Connect products to categories
    ON p.category_id = c.category_id         -- Match category IDs

GROUP BY
    c.category_name                          -- Calculate profit per category

ORDER BY
    gross_profit DESC;                       -- Highest-profit category first
    
    
    
    -- =====================================================
-- PROJECT 2: SALES PERFORMANCE ANALYSIS
-- TASK 23: GROSS PROFIT MARGIN BY CATEGORY
-- Business Question:
-- What percentage of revenue is retained as
-- gross profit in each category?
-- =====================================================

SELECT
    c.category_name,                         -- Identify the product category

    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS total_revenue,                      -- Revenue after discounts

    SUM(
        (
            oi.unit_price
            * (1 - oi.discount_percent / 100)
            - p.cost_price
        )
        * oi.quantity
    ) AS gross_profit,                       -- Gross profit after product costs

    (
        SUM(
            (
                oi.unit_price
                * (1 - oi.discount_percent / 100)
                - p.cost_price
            )
            * oi.quantity
        )
        /
        SUM(
            oi.quantity
            * oi.unit_price
            * (1 - oi.discount_percent / 100)
        )
    ) * 100 AS gross_profit_margin           -- Gross profit as % of revenue

FROM order_items AS oi                       -- Start with sales line items
JOIN products AS p                           -- Connect items to product costs
    ON oi.product_id = p.product_id          -- Match product IDs

JOIN categories AS c                         -- Connect products to categories
    ON p.category_id = c.category_id         -- Match category IDs

GROUP BY
    c.category_name                          -- Calculate metrics per category

ORDER BY
    gross_profit_margin DESC;                -- Highest margin first
    
    
    -- =====================================================
-- PROJECT 2: SALES PERFORMANCE ANALYSIS
-- TASK 24: GROSS PROFIT BY SALES CHANNEL
-- Business Question:
-- How much gross profit does each sales channel generate?
-- =====================================================

SELECT
    o.channel,                               -- Identify the sales channel

    SUM(
        (
            oi.unit_price
            * (1 - oi.discount_percent / 100)
            - p.cost_price
        )
        * oi.quantity
    ) AS gross_profit                        -- Calculate gross profit

FROM orders AS o                             -- Start with orders
JOIN order_items AS oi                       -- Connect orders to their items
    ON o.order_id = oi.order_id              -- Match order IDs

JOIN products AS p                           -- Connect items to product costs
    ON oi.product_id = p.product_id          -- Match product IDs

GROUP BY
    o.channel                                -- Calculate profit per channel

ORDER BY
    gross_profit DESC;                       -- Highest-profit channel first
    
    
    
    -- =====================================================
