-- PROJECT 2: SALES PERFORMANCE ANALYSIS
-- TASK 30: REVENUE, PROFIT & MARGIN BY YEAR AND CHANNEL
-- Business Question:
-- How do revenue, gross profit, and gross margin vary
-- across each year and sales channel?
-- =====================================================

SELECT
    YEAR(o.order_date) AS order_year,        -- Extract the year
    o.channel,                               -- Identify the sales channel

    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS total_revenue,                      -- Revenue after discounts

    SUM(
        (
            oi.unit_price
            * (1 - oi.discount_percent / 100)
            - p.cost_price
        )
        * oi.quantity
    ) AS gross_profit,                       -- Gross profit after product costs

    (
        SUM(
            (
                oi.unit_price
                * (1 - oi.discount_percent / 100)
                - p.cost_price
            )
            * oi.quantity
        )
        /
        SUM(
            oi.quantity
            * oi.unit_price
            * (1 - oi.discount_percent / 100)
        )
    ) * 100 AS gross_profit_margin           -- Gross profit as % of revenue

FROM orders AS o                             -- Start with orders
JOIN order_items AS oi                       -- Connect orders to their items
    ON o.order_id = oi.order_id              -- Match order IDs

JOIN products AS p                           -- Connect items to product costs
    ON oi.product_id = p.product_id          -- Match product IDs

GROUP BY
    YEAR(o.order_date),
    o.channel                                -- Group by year and channel

ORDER BY
    order_year,
    o.channel;                               -- Sort chronologically by year
    
    
    
    -- =====================================================
-- PROJECT 2: SALES PERFORMANCE ANALYSIS
-- TASK 31: MONTHLY REVENUE AND GROSS PROFIT
-- Business Question:
-- How do revenue and gross profit change month by month?
-- =====================================================

SELECT
    YEAR(o.order_date) AS order_year,        -- Extract the year
    MONTH(o.order_date) AS order_month,      -- Extract the month number

    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS total_revenue,                      -- Monthly revenue after discounts

    SUM(
        (
            oi.unit_price
            * (1 - oi.discount_percent / 100)
            - p.cost_price
        )
        * oi.quantity
    ) AS gross_profit                        -- Monthly gross profit

FROM orders AS o                             -- Start with orders
JOIN order_items AS oi                       -- Connect orders to their items
    ON o.order_id = oi.order_id              -- Match order IDs

JOIN products AS p                           -- Connect items to product costs
    ON oi.product_id = p.product_id          -- Match product IDs

GROUP BY
    YEAR(o.order_date),
    MONTH(o.order_date)                      -- Create one group per year/month

ORDER BY
    order_year,
    order_month;                             -- Display chronologically
    
    
    
    
-- =====================================================
-- PROJECT 2: SALES PERFORMANCE ANALYSIS
-- TASK 32: MONTHLY GROSS PROFIT MARGIN
-- Business Question:
-- Does NovaMart's gross profit margin change
-- significantly from month to month?
-- =====================================================

SELECT
    YEAR(o.order_date) AS order_year,        -- Extract the year
    MONTH(o.order_date) AS order_month,      -- Extract the month number

    -- Calculate total revenue after discounts
    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS total_revenue,

    -- Calculate gross profit after product cost
    SUM(
        (
            oi.unit_price
            * (1 - oi.discount_percent / 100)
            - p.cost_price
        )
        * oi.quantity
    ) AS gross_profit,

    -- Calculate gross profit margin as a percentage
    (
        SUM(
            (
                oi.unit_price
                * (1 - oi.discount_percent / 100)
                - p.cost_price
            )
            * oi.quantity
        )
        /
        SUM(
            oi.quantity
            * oi.unit_price
            * (1 - oi.discount_percent / 100)
        )
    ) * 100 AS gross_profit_margin

FROM orders AS o
JOIN order_items AS oi
    ON o.order_id = oi.order_id

JOIN products AS p
    ON oi.product_id = p.product_id

GROUP BY
    YEAR(o.order_date),
    MONTH(o.order_date)

ORDER BY
    order_year,
    order_month;
    
    
    -- =====================================================
-- PROJECT 2: SALES PERFORMANCE ANALYSIS
-- TASK 33: YEAR-OVER-YEAR REVENUE GROWTH
-- Business Question:
-- How did NovaMart's revenue change from 2025 to 2026?
-- =====================================================

SELECT
    YEAR(o.order_date) AS order_year,       -- Extract the year

    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS total_revenue                      -- Revenue after discounts

FROM orders AS o
JOIN order_items AS oi
    ON o.order_id = oi.order_id

WHERE MONTH(o.order_date) <= 9              -- Compare Jan-Sep only

GROUP BY
    YEAR(o.order_date)

ORDER BY
    order_year;
    
    
    
    -- =====================================================
-- PROJECT 2: SALES PERFORMANCE ANALYSIS
-- TASK 34: YEAR-OVER-YEAR REVENUE GROWTH %
-- Business Question:
-- What was NovaMart's revenue growth or decline
-- from Jan-Sep 2025 to Jan-Sep 2026?
-- =====================================================

SELECT
    (
        (
            SUM(
                CASE
                    WHEN YEAR(o.order_date) = 2026 THEN
                        oi.quantity
                        * oi.unit_price
                        * (1 - oi.discount_percent / 100)
                    ELSE 0
                END
            )
            -
            SUM(
                CASE
                    WHEN YEAR(o.order_date) = 2025 THEN
                        oi.quantity
                        * oi.unit_price
                        * (1 - oi.discount_percent / 100)
                    ELSE 0
                END
            )
        )
        /
        SUM(
            CASE
                WHEN YEAR(o.order_date) = 2025 THEN
                    oi.quantity
                    * oi.unit_price
                    * (1 - oi.discount_percent / 100)
                ELSE 0
            END
        )
    ) * 100 AS yoy_revenue_growth_percent

FROM orders AS o
JOIN order_items AS oi
    ON o.order_id = oi.order_id

WHERE MONTH(o.order_date) <= 9;




-- =====================================================
-- PROJECT 2: SALES PERFORMANCE ANALYSIS
-- TASK 35: YEAR-OVER-YEAR GROSS PROFIT GROWTH %
-- Business Question:
-- Did NovaMart's gross profit grow or decline
-- from Jan-Sep 2025 to Jan-Sep 2026?
-- =====================================================

SELECT
    (
        (
            -- Gross profit generated in Jan-Sep 2026
            SUM(
                CASE
                    WHEN YEAR(o.order_date) = 2026 THEN
                        (
                            oi.unit_price
                            * (1 - oi.discount_percent / 100)
                            - p.cost_price
                        ) * oi.quantity
                    ELSE 0
                END
            )

            -

            -- Gross profit generated in Jan-Sep 2025
            SUM(
                CASE
                    WHEN YEAR(o.order_date) = 2025 THEN
                        (
                            oi.unit_price
                            * (1 - oi.discount_percent / 100)
                            - p.cost_price
                        ) * oi.quantity
                    ELSE 0
                END
            )
        )

        /

        -- Jan-Sep 2025 gross profit is the baseline
        SUM(
            CASE
                WHEN YEAR(o.order_date) = 2025 THEN
                    (
                        oi.unit_price
                        * (1 - oi.discount_percent / 100)
                        - p.cost_price
                    ) * oi.quantity
                ELSE 0
            END
        )
    ) * 100 AS yoy_gross_profit_growth_percent

FROM orders AS o

JOIN order_items AS oi
    ON o.order_id = oi.order_id

JOIN products AS p
    ON oi.product_id = p.product_id

WHERE MONTH(o.order_date) <= 9;


-- =====================================================
-- PROJECT 2: SALES PERFORMANCE ANALYSIS
-- TASK 36: YOY REVENUE BY SALES CHANNEL
-- Business Question:
-- How did revenue change for each sales channel
-- from Jan-Sep 2025 to Jan-Sep 2026?
-- =====================================================

SELECT
    o.channel,                              -- Sales channel

    -- Revenue from Jan-Sep 2025
    SUM(
        CASE
            WHEN YEAR(o.order_date) = 2025 THEN
                oi.quantity
                * oi.unit_price
                * (1 - oi.discount_percent / 100)
            ELSE 0
        END
    ) AS revenue_2025,

    -- Revenue from Jan-Sep 2026
    SUM(
        CASE
            WHEN YEAR(o.order_date) = 2026 THEN
                oi.quantity
                * oi.unit_price
                * (1 - oi.discount_percent / 100)
            ELSE 0
        END
    ) AS revenue_2026,

    -- Calculate percentage growth/decline
    (
        (
            SUM(
                CASE
                    WHEN YEAR(o.order_date) = 2026 THEN
                        oi.quantity
                        * oi.unit_price
                        * (1 - oi.discount_percent / 100)
                    ELSE 0
                END
            )
            -
            SUM(
                CASE
                    WHEN YEAR(o.order_date) = 2025 THEN
                        oi.quantity
                        * oi.unit_price
                        * (1 - oi.discount_percent / 100)
                    ELSE 0
                END
            )
        )
        /
        SUM(
            CASE
                WHEN YEAR(o.order_date) = 2025 THEN
                    oi.quantity
                    * oi.unit_price
                    * (1 - oi.discount_percent / 100)
                ELSE 0
            END
        )
    ) * 100 AS yoy_growth_percent

FROM orders AS o

JOIN order_items AS oi
    ON o.order_id = oi.order_id

WHERE MONTH(o.order_date) <= 9

GROUP BY
    o.channel

ORDER BY
    yoy_growth_percent DESC;
    
    
    -- =====================================================
-- PROJECT 2: SALES PERFORMANCE ANALYSIS
-- TASK 37: YOY GROSS PROFIT BY SALES CHANNEL
-- Business Question:
-- How did gross profit change for each sales channel
-- from Jan-Sep 2025 to Jan-Sep 2026?
-- =====================================================

SELECT
    o.channel,                              -- Sales channel

    -- Gross profit from Jan-Sep 2025
    SUM(
        CASE
            WHEN YEAR(o.order_date) = 2025 THEN
                (
                    oi.unit_price
                    * (1 - oi.discount_percent / 100)
                    - p.cost_price
                ) * oi.quantity
            ELSE 0
        END
    ) AS gross_profit_2025,

    -- Gross profit from Jan-Sep 2026
    SUM(
        CASE
            WHEN YEAR(o.order_date) = 2026 THEN
                (
                    oi.unit_price
                    * (1 - oi.discount_percent / 100)
                    - p.cost_price
                ) * oi.quantity
            ELSE 0
        END
    ) AS gross_profit_2026,

    -- Calculate YoY gross profit growth/decline
    (
        (
            SUM(
                CASE
                    WHEN YEAR(o.order_date) = 2026 THEN
                        (
                            oi.unit_price
                            * (1 - oi.discount_percent / 100)
                            - p.cost_price
                        ) * oi.quantity
                    ELSE 0
                END
            )
            -
            SUM(
                CASE
                    WHEN YEAR(o.order_date) = 2025 THEN
                        (
                            oi.unit_price
                            * (1 - oi.discount_percent / 100)
                            - p.cost_price
                        ) * oi.quantity
                    ELSE 0
                END
            )
        )
        /
        SUM(
            CASE
                WHEN YEAR(o.order_date) = 2025 THEN
                    (
                        oi.unit_price
                        * (1 - oi.discount_percent / 100)
                        - p.cost_price
                    ) * oi.quantity
                ELSE 0
            END
        )
    ) * 100 AS yoy_growth_percent

FROM orders AS o

JOIN order_items AS oi
    ON o.order_id = oi.order_id

JOIN products AS p
    ON oi.product_id = p.product_id

WHERE MONTH(o.order_date) <= 9

GROUP BY
    o.channel

ORDER BY
    yoy_growth_percent DESC;
    
    
    
    
    -- =====================================================
-- PROJECT 2: SALES PERFORMANCE ANALYSIS
-- TASK 38: REVENUE AND GROSS PROFIT BY REGION
-- Business Question:
-- How are NovaMart's regions performing in revenue
-- and gross profit?
-- =====================================================

SELECT
    s.region,                               -- Store region

    -- Calculate revenue after discounts
    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS total_revenue,

    -- Calculate gross profit after product cost
    SUM(
        (
            oi.unit_price
            * (1 - oi.discount_percent / 100)
            - p.cost_price
        ) * oi.quantity
    ) AS gross_profit,

    -- Calculate gross profit margin
    (
        SUM(
            (
                oi.unit_price
                * (1 - oi.discount_percent / 100)
                - p.cost_price
            ) * oi.quantity
        )
        /
        SUM(
            oi.quantity
            * oi.unit_price
            * (1 - oi.discount_percent / 100)
        )
    ) * 100 AS gross_profit_margin

FROM orders AS o

JOIN order_items AS oi
    ON o.order_id = oi.order_id

JOIN products AS p
    ON oi.product_id = p.product_id

JOIN stores AS s
    ON o.store_id = s.store_id

GROUP BY
    s.region

ORDER BY
    total_revenue DESC;
    
    
    
    -- =====================================================
