    -- Calculate revenue after discounts
    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS total_revenue,

    -- Calculate gross profit after product cost
    SUM(
        (
            oi.unit_price
            * (1 - oi.discount_percent / 100)
            - p.cost_price
        ) * oi.quantity
    ) AS gross_profit,

    -- Calculate gross profit margin
    (
        SUM(
            (
                oi.unit_price
                * (1 - oi.discount_percent / 100)
                - p.cost_price
            ) * oi.quantity
        )
        /
        SUM(
            oi.quantity
