    -- =====================================================
-- PROJECT 2: SALES PERFORMANCE ANALYSIS
-- TASK 40: REVENUE AND GROSS PROFIT BY CUSTOMER REGION
-- Business Question:
-- Where are NovaMart's customers generating
-- the most revenue?
-- =====================================================

SELECT
    c.region,                               -- Customer's region

    -- Calculate revenue after discounts
    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS total_revenue,

    -- Calculate gross profit after product cost
    SUM(
        (
            oi.unit_price
            * (1 - oi.discount_percent / 100)
            - p.cost_price
        ) * oi.quantity
    ) AS gross_profit,

    -- Calculate gross profit margin
    (
        SUM(
            (
                oi.unit_price
                * (1 - oi.discount_percent / 100)
                - p.cost_price
            ) * oi.quantity
        )
        /
        SUM(
            oi.quantity
            * oi.unit_price
            * (1 - oi.discount_percent / 100)
        )
    ) * 100 AS gross_profit_margin

FROM orders AS o

JOIN order_items AS oi
    ON o.order_id = oi.order_id

JOIN products AS p
    ON oi.product_id = p.product_id

JOIN customers AS c
    ON o.customer_id = c.customer_id

GROUP BY
    c.region

ORDER BY
    total_revenue DESC;
    
